<?php require __DIR__.'/app/bootstrap.php';Auth::requireLogin();$q=trim($_GET['q']??'');$s=db()->prepare("SELECT id,title,platform,status,created_at FROM transcripts WHERE user_id=? AND (title LIKE ? OR transcript_text LIKE ? OR source_url LIKE ?) ORDER BY id DESC LIMIT 100");$s->execute([Auth::id(),'%'.$q.'%','%'.$q.'%','%'.$q.'%']);$items=$s->fetchAll();$pageTitle='My transcripts';require __DIR__.'/app/views/header.php';?><main class="app-shell"><div class="container"><h1 class="h2 fw-bold">My transcripts</h1><section class="panel-card"><form class="d-flex gap-2 mb-3"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search your transcripts"><button class="btn btn-outline-primary">Search</button></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Transcript</th><th>Platform</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><a href="<?=e(url('transcript.php?id='.$it['id']))?>"><?=e($it['title']?:$it['platform'].' transcript')?></a></td><td><?=e($it['platform'])?></td><td><span class="status-pill status-<?=e($it['status'])?>"><?=e($it['status'])?></span></td><td><?=e(date('d M Y',strtotime($it['created_at'])))?></td></tr><?php endforeach?><?php if(!$items):?><tr><td colspan="4" class="text-center text-secondary py-5">No transcripts found.</td></tr><?php endif?></tbody></table></div></section></div></main><?php require __DIR__.'/app/views/footer.php';?>
